import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 1000000007;
    static final long INF = (long) 1e18;
    static long[][] comb = new long[61][61];
    static int R, C;
    static String S;
    static ArrayList<Pair>[] dpL = new ArrayList[31];
    static ArrayList<Pair>[] dpR = new ArrayList[31];
    static long ans = 0;

    static class Pair {
        long first;
        int second;
        Pair(long f, int s) {
            first = f;
            second = s;
        }
    }

    static long calc(String t) {
        long ans = 0;
        int a = 0, b = 0;
        for (char c : t.toCharArray()) {
            if (c == 'A') {
                a++;
                ans += (comb[a][R] - comb[a - 1][R]) * (comb[R + C][R] - comb[b][R]);
            } else {
                b++;
                ans -= (comb[b][R] - comb[b - 1][R]) * (comb[R + C][R] - comb[a][R]);
            }
        }
        if (a != b) return INF;
        return ans;
    }

    static boolean match(String t) {
        for (int i = 0; i < S.length(); i++) {
            if (S.charAt(i) != '?' && S.charAt(i) != t.charAt(i)) return false;
        }
        return true;
    }

    static void init() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());
        S = st.nextToken();
        for (int i = 0; i <= 60; i++) {
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }
        for (int i = 0; i < 31; i++) {
            dpL[i] = new ArrayList<>();
            dpR[i] = new ArrayList<>();
        }
    }

    static void dfsL(int id, int a, int b, int mask, long p) {
        if (id == C + 1) {
            dpL[a].add(new Pair(p, mask));
            return;
        }
        dfsL(id + 1, a + 1, b, mask ^ (1 << id), p + (comb[a + 1][R] - comb[a][R]) * (comb[R + C][R] - comb[b][R]));
        dfsL(id + 1, a, b + 1, mask, p - (comb[b + 1][R] - comb[b][R]) * (comb[R + C][R] - comb[a][R]));
    }

    static void dfsR(int id, int a, int b, int mask, long p) {
        if (id == C + 1) {
            dpR[a].add(new Pair(p, mask));
            return;
        }
        dfsR(id + 1, a - 1, b, mask ^ (1 << id), p + (comb[a][R] - comb[a - 1][R]) * (comb[R + C][R] - comb[b][R]));
        dfsR(id + 1, a, b - 1, mask, p - (comb[b][R] - comb[b - 1][R]) * (comb[R + C][R] - comb[a][R]));
    }

    static int rev(int x, int y) {
        int z = 0;
        for (int i = 0; i < y; i++) {
            if ((x & (1 << i)) != 0) z ^= (1 << (y - 1 - i));
        }
        return z;
    }

    static void check(long x, int t) {
        int a = 0, b = 0;
        for (int i = 0; i <= 2 * C + 1; i++) {
            if ((x & (1L << i)) != 0) a++;
            else b++;
            if (a > 0 && b > 0) {
                for (int j = i; j <= 2 * C + 1; j++) {
                    if ((x & (1L << j)) != 0) {
                        if (S.charAt(S.length() - (2 * C + 2) + j) == 'B') return;
                    } else {
                        if (S.charAt(S.length() - (2 * C + 2) + j) == 'A') return;
                    }
                }
                int aa = 0, bb = 0;
                for (int j = 0; j < S.length() - (2 * C + 2) + i; j++) {
                    if (S.charAt(j) == 'A') aa++;
                    if (S.charAt(j) == 'B') bb++;
                }
                long tmp;
                if ((x & (1L << i)) != 0) {
                    tmp = comb[R - 1 - aa + b + R - 1 - bb][R - 1 - aa];
                } else {
                    tmp = comb[a + R - 1 - aa + R - 1 - bb][a + R - 1 - aa];
                }
                ans += t * tmp;
                return;
            }
        }
    }

    static boolean ok(long x) {
        for (int i = 0; i <= C; i++) {
            if ((x & (1L << i)) != 0) {
                if (S.charAt(S.length() - C - 1 + i) == 'B') return false;
            } else {
                if (S.charAt(S.length() - C - 1 + i) == 'A') return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        init();
        dfsL(0, R - 1, R - 1, 0, 0);
        dfsR(0, R + C, R + C, 0, 0);
        long dif = INF;
        for (int i = 0; i <= R + C; i++) {
            Collections.sort(dpL[i], (p1, p2) -> Long.compare(p1.first, p2.first));
            Collections.sort(dpR[i], (p1, p2) -> Long.compare(p2.first, p1.first));
            int idx = 0;
            for (Pair p : dpL[i]) {
                while (idx + 1 < dpR[i].size() && p.first + dpR[i].get(idx + 1).first >= 0) idx++;
                dif = Math.min(dif, Math.abs(p.first + dpR[i].get(idx).first));
                if (idx + 1 < dpR[i].size()) {
                    dif = Math.min(dif, Math.abs(p.first + dpR[i].get(idx + 1).first));
                }
            }
        }
        for (int i = 0; i <= R + C; i++) {
            ArrayList<Pair> z = new ArrayList<>();
            for (Pair p : dpR[i]) {
                if (ok(rev(p.second, C + 1))) z.add(p);
            }
            int l = 0, r = -1;
            for (Pair p : dpL[i]) {
                while (l < z.size() && p.first + z.get(l).first > dif) l++;
                while (r + 1 < z.size() && p.first + z.get(r + 1).first >= -dif) r++;
                if (l <= r) {
                    check(p.second | ((long) rev(z.get(l).second, C + 1) << (C + 1)), r - l + 1);
                }
            }
        }
        System.out.println(ans);
    }
}
